// PROJETO SM3 — CONTENT PLAN QUEUE v3 HARDENED
// New plans use PLAN_VERSION V2, but an unchanged existing plan is NOT regenerated
// only because its historical version is older.
//
// Structural Vision and format viability are operational constraints.

const projects = $('READ — CURATED PROJECTS').all().map(i => i.json);
const mediaRows = $('READ — CURATED MEDIA').all().map(i => i.json);
const templates = $('READ — ACTIVE TEMPLATES').all().map(i => i.json);
const contentRows = $('READ — EXISTING CONTENT').all().map(i => i.json);
const configRows = $('READ — OS CONFIG').all().map(i => i.json);

const PLAN_VERSION = 'SM3_CONTENT_PLAN_V2_STRUCTURAL';

function upper(v){ return String(v || '').trim().toUpperCase(); }
function configValue(key, fallback) {
  const row = configRows.find(r => String(r.CHAVE || '').trim() === key);
  if (!row) return fallback;
  if (upper(row.TIPO) === 'BOOLEAN') return row.VALOR === true || upper(row.VALOR) === 'TRUE';
  if (upper(row.TIPO) === 'NUMBER') {
    const n = Number(row.VALOR);
    return Number.isFinite(n) ? n : fallback;
  }
  return row.VALOR ?? fallback;
}

const minFormatViability = Number(configValue('content.min_format_viability', 55));
if (!Number.isFinite(minFormatViability) || minFormatViability < 0 || minFormatViability > 100) {
  throw new Error(`CONTENT_PLAN_CONFIG_BLOCK: invalid min format viability ${minFormatViability}`);
}

const activeTemplates = templates
  .filter(t => upper(t.STATUS) === 'ATIVO')
  .map(t => ({
    template_id: t.ID_TEMPLATE,
    name: t.NOME,
    format: t.FORMATO,
    dimension: t.DIMENSAO || '',
    composition_profile: t.PERFIL_MOTOR || '',
    media_zone: t.ZONA_MIDIA || '',
    text_zone: t.ZONA_TEXTO || '',
    signature: t.ASSINATURA || '',
    crop_rule: t.REGRA_CROP || '',
    text_rule: t.REGRA_TEXTO || ''
  }));

const out = [];
const audit = [];

for (const p of projects) {
  const pid = String(p.ID_PROJETO || '').trim();
  if (!pid) continue;

  const reasons = [];
  const storage = upper(p.STORAGE_STATUS);
  const curationStatus = upper(p.CURATION_STATUS);
  const curationRun = String(p.CURATION_RUN_ID || '').trim();

  if (storage !== 'ONLINE') reasons.push(`STORAGE_STATUS=${storage || 'EMPTY'}`);
  if (curationStatus !== 'AI_CURATED') reasons.push(`CURATION_STATUS=${curationStatus || 'EMPTY'}`);
  if (!curationRun) reasons.push('CURATION_RUN_ID=EMPTY');

  const curated = mediaRows
    .filter(m =>
      String(m.ID_PROJETO || '').trim() === pid &&
      upper(m.STORAGE_STATUS) === 'ONLINE' &&
      upper(m.CURATION_STATUS) === 'AI_CURATED' &&
      upper(m.CURATION_ROLE) !== 'DISCARD'
    )
    .map(m => {
      const type = upper(m.TIPO);
      const kind = type.includes('VÍDEO') || type.includes('VIDEO') ? 'video' : 'image';
      return {
        media_id: m.ID_MIDIA,
        kind,
        curation_role: m.CURATION_ROLE || '',
        curation_rank: Number(m.CURATION_RANK || 0) || null,
        stage: m.ANALYSIS_STAGE || '',
        shot_type: m.SHOT_TYPE || '',
        visual_summary: m['CONTEÚDO_VISUAL'] || '',
        recommended_use: m.USAR_EM || '',
        best_moment: m.MELHOR_TRECHO || '',

        structural_analysis_version: m.STRUCTURAL_ANALYSIS_VERSION || '',
        geometry_mode: m.GEOMETRY_MODE || '',
        body_region: m.BODY_REGION || '',
        body_subregion: m.BODY_SUBREGION || '',
        view_angle: m.VIEW_ANGLE || '',
        body_pose: m.BODY_POSE || '',
        tattoo_orientation: m.TATTOO_ORIENTATION || '',
        tattoo_style_tags: m.TATTOO_STYLE_TAGS || '',
        tattoo_subject_primary: m.TATTOO_SUBJECT_PRIMARY || '',
        tattoo_subject_tags: m.TATTOO_SUBJECT_TAGS || '',
        tattoo_stage_structural: m.TATTOO_STAGE_STRUCTURAL || '',
        tattoo_coverage: m.TATTOO_COVERAGE || '',
        composition_shape: m.COMPOSITION_SHAPE || '',
        focal_description: m.FOCAL_DESCRIPTION || '',
        crop_guidance_json: m.CROP_GUIDANCE_JSON || '',
        format_fit_json: m.FORMAT_FIT_JSON || '',
        best_formats: m.BEST_FORMATS || '',
        structural_confidence: Number(m.STRUCTURAL_CONFIDENCE || 0)
      };
    })
    .sort((a,b)=>(a.curation_rank || 999)-(b.curation_rank || 999));

  if (curated.length === 0) reasons.push('NO_NON_DISCARD_CURATED_MEDIA');

  // Existing current plans are keyed by the curation run, not by planner software version.
  const matchingPlanRows = contentRows.filter(r =>
    String(r.ID_PROJETO || '').trim() === pid &&
    upper(r.PLAN_STATUS) === 'AI_PLANNED' &&
    String(r.CURATION_RUN_ID || '').trim() === curationRun
  );

  const projectStateCurrent =
    upper(p.CONTENT_PLAN_STATUS) === 'AI_PLANNED' &&
    String(p.CONTENT_PLAN_CURATED_FROM || '').trim() === curationRun;

  let route = 'SKIP';
  if (reasons.length === 0) {
    if (matchingPlanRows.length === 0) route = 'PLAN';
    else if (!projectStateCurrent) route = 'REPAIR';
    else route = 'CURRENT';
  }

  audit.push({
    project_id: pid,
    eligible_base: reasons.length === 0,
    exclusion_reasons: reasons,
    matching_plan_rows: matchingPlanRows.length,
    project_state_current: projectStateCurrent,
    structural_media: curated.filter(m => upper(m.structural_analysis_version) === 'SM3_STRUCTURAL_V1').length,
    route
  });

  if (reasons.length > 0 || route === 'CURRENT') continue;

  if (route === 'REPAIR') {
    const first = matchingPlanRows[0] || {};
    out.push({
      json: {
        route_key: 'REPAIR',
        project_id: pid,
        project_write: {
          ID_PROJETO: pid,
          CONTENT_PLAN_STATUS: 'AI_PLANNED',
          CONTENT_PLAN_VERSION: first.PLAN_VERSION || PLAN_VERSION,
          CONTENT_PLAN_RUN_ID: first.PLAN_RUN_ID || '',
          CONTENT_PLAN_CURATED_FROM: curationRun,
          CONTENT_PLAN_AT: first.GENERATED_AT || new Date().toISOString(),
          CONTENT_PLAN_COUNT: matchingPlanRows.length,
          CONTENT_PLAN_PROVIDER: first.PLAN_PROVIDER || '',
          CONTENT_PLAN_MODEL: first.PLAN_MODEL || ''
        },
        eligibility_audit: audit
      }
    });
    continue;
  }

  out.push({
    json: {
      route_key: 'PLAN',
      no_work: false,
      project_id: pid,
      curation_run_id: curationRun,
      hero_id: p.CURATION_HERO_ID || '',
      narrative: p.CURATION_NARRATIVE || '',
      carousel_order: String(p.CURATION_CAROUSEL_ORDER || '').split(',').map(x=>x.trim()).filter(Boolean),
      reel_candidate_ids: String(p.CURATION_REEL_IDS || '').split(',').map(x=>x.trim()).filter(Boolean),
      media: curated,
      templates: activeTemplates,
      min_format_viability: minFormatViability,
      context:
        'Planejar conteúdo sem publicar/agendar. Structural Vision e format fit são restrições. Editorial Gate humano é obrigatório antes da produção e Final Approval humano será obrigatório após QA.',
      eligibility_audit: audit
    }
  });
}

if (out.length === 0) {
  return [{
    json: {
      route_key: 'NO_WORK',
      no_work: true,
      status: 'CONTENT_PLAN_CURRENT_OR_NOT_ELIGIBLE',
      message: 'Nenhum projeto precisa de novo plano de conteúdo.',
      eligibility_audit: audit,
      checked_at: new Date().toISOString()
    }
  }];
}

return out;

return $input.all().map(i => ({json:{
  ...i.json,
  completed:true,
  status:'NO_CHANGES',
  message:'Plano de conteúdo já está atual ou o projeto não é elegível; nenhuma chamada de IA foi necessária.'
}}));

function fitKey(format, dimension) {
  const f = String(format || '').trim().toUpperCase();
  const d = String(dimension || '').toLowerCase().replace(/\s/g,'');
  if (f === 'REEL') return 'reel_9x16';
  if (f === 'STORY') return 'story_9x16';
  if (d.includes('1080x1080') || d.includes('1:1')) return 'square_1x1';
  if (d.includes('1920x1080') || d.includes('16:9')) return 'landscape_16x9';
  return 'feed_4x5';
}
function parseJson(v) {
  try { return v && typeof v === 'object' ? v : JSON.parse(String(v || '{}')); }
  catch { return {}; }
}

const queueByProject = new Map(
  $('BUILD — CONTENT PLAN QUEUE').all()
    .map(i => i.json)
    .filter(x => x.route_key === 'PLAN')
    .map(x => [String(x.project_id), x])
);

return $input.all().map(i => {
  const x = i.json;
  const p = x.plan || {};
  const plans = Array.isArray(p.plans) ? p.plans : [];
  const q = queueByProject.get(String(x.project_id)) || {};
  const threshold = Number(q.min_format_viability ?? 55);
  const mediaById = new Map((q.media || []).map(m => [String(m.media_id), m]));
  const templateById = new Map((q.templates || []).map(t => [String(t.template_id), t]));

  if (!x.project_id || !x.curation_run_id || !x.response_id) {
    throw new Error('CONTENT_PLAN_WRITE_BLOCK: missing project/curation/response identity');
  }
  if (plans.length < 1 || plans.length > 4) {
    throw new Error(`CONTENT_PLAN_WRITE_BLOCK: invalid plan count ${plans.length}`);
  }

  const seen = new Set();

  for (const plan of plans) {
    const key = String(plan.plan_key || '').trim();
    if (!key || seen.has(key)) throw new Error(`CONTENT_PLAN_WRITE_BLOCK: invalid/duplicate plan_key ${key}`);
    seen.add(key);

    if (!Array.isArray(plan.media_ids) || plan.media_ids.length === 0) {
      throw new Error(`CONTENT_PLAN_WRITE_BLOCK: no media for ${key}`);
    }

    const templateId = String(plan.template_id || '').trim();
    const template = templateById.get(templateId);
    if (!template) throw new Error(`CONTENT_PLAN_WRITE_BLOCK: invalid template ${templateId} for ${key}`);

    const fitKeyName = fitKey(plan.format, template.dimension);

    for (const id of plan.media_ids) {
      const m = mediaById.get(String(id));
      if (!m) throw new Error(`CONTENT_PLAN_WRITE_BLOCK: unknown media ${id} for ${key}`);

      const fit = parseJson(m.format_fit_json);
      const entry = fit[fitKeyName] || {};
      const strategy = String(entry.strategy || '').toUpperCase();
      const score = Number(entry.viability_score);

      // Legacy rows without structural fit are allowed only when no structural version exists.
      const structuralPresent = String(m.structural_analysis_version || '').toUpperCase().startsWith('SM3_STRUCTURAL_V');
      if (structuralPresent) {
        if (strategy === 'NOT_RECOMMENDED') {
          throw new Error(`CONTENT_PLAN_FORMAT_BLOCK: ${id}/${fitKeyName}/NOT_RECOMMENDED`);
        }
        if (!Number.isFinite(score) || score < threshold) {
          throw new Error(`CONTENT_PLAN_FORMAT_BLOCK: ${id}/${fitKeyName}/${score}<${threshold}`);
        }
      }
    }
  }

  return {
    json: {
      project_id: x.project_id,
      curation_run_id: x.curation_run_id,
      provider: x.provider,
      model: x.model,
      response_id: x.response_id,
      project_strategy: p.project_strategy || '',
      confidence: Number(p.confidence || 0),
      plans,
      min_format_viability: threshold
    }
  };
});

// PROJETO SM3 — BUILD CONTENT ROWS
// Generates collision-free IDs against the existing 04_CONTEUDOS snapshot.
// Human approval is ALWAYS PENDENTE.

const inputs = $input.all().map(i => i.json);
const existing = $('READ — EXISTING CONTENT').all().map(i => i.json);
const mediaRows = $('READ — CURATED MEDIA').all().map(i => i.json);
const templateRows = $('READ — ACTIVE TEMPLATES').all().map(i => i.json);
const templateById = new Map(templateRows.map(t => [String(t.ID_TEMPLATE || ''), t]));

const PLAN_VERSION = 'SM3_CONTENT_PLAN_V2_STRUCTURAL';
const now = new Date().toISOString();

const counters = {
  REEL: 0,
  CARROSSEL: 0,
  POST: 0,
  STORY: 0
};

for (const r of existing) {
  const id = String(r.ID_CONTEÚDO || '').trim().toUpperCase();
  const m = id.match(/^(REEL|CARROSSEL|POST|STORY)_(\d+)$/);
  if (!m) continue;
  counters[m[1]] = Math.max(counters[m[1]], Number(m[2]) || 0);
}

const mediaById = new Map(
  mediaRows
    .filter(r => String(r.ID_MIDIA || '').trim())
    .map(r => [String(r.ID_MIDIA).trim(), r])
);

function prefixFor(format) {
  const f = String(format || '').trim().toUpperCase();
  if (f === 'REEL') return 'REEL';
  if (f === 'CARROSSEL') return 'CARROSSEL';
  if (f === 'STORY') return 'STORY';
  if (f === 'FOTO') return 'POST';
  throw new Error(`CONTENT_PLAN_WRITE_BLOCK: unsupported format ${format}`);
}

function normalizePriority(v) {
  const p = String(v || '').trim().toUpperCase();
  if (p === 'MEDIA') return 'MÉDIA';
  return ['ALTA','MÉDIA','BAIXA'].includes(p) ? p : 'MÉDIA';
}

function deriveSessions(mediaIds) {
  const sessions = new Set();
  for (const id of mediaIds) {
    const r = mediaById.get(id) || {};
    let s = String(r['SESSÃO'] || '').trim();
    if (!s) {
      const rel = String(r.RELATIVE_PATH || '').trim();
      const m = rel.match(/(?:^|\/)(S\d{2,3})(?:\/|$)/i);
      if (m) s = m[1].toUpperCase();
    }
    if (s) sessions.add(s);
  }
  return [...sessions].sort().join(',');
}

const out = [];

for (const x of inputs) {
  const projectWrite = {
    ID_PROJETO: x.project_id,
    CONTENT_PLAN_STATUS: 'AI_PLANNED',
    CONTENT_PLAN_VERSION: PLAN_VERSION,
    CONTENT_PLAN_RUN_ID: x.response_id,
    CONTENT_PLAN_CURATED_FROM: x.curation_run_id,
    CONTENT_PLAN_AT: now,
    CONTENT_PLAN_COUNT: x.plans.length,
    CONTENT_PLAN_PROVIDER: x.provider || '',
    CONTENT_PLAN_MODEL: x.model || ''
  };

  const rows = x.plans.map((p, index) => {
    const prefix = prefixFor(p.format);
    counters[prefix] += 1;
    const id = `${prefix}_${String(counters[prefix]).padStart(4, '0')}`;

    const mediaIds = (p.media_ids || []).map(String);
    const platforms = Array.isArray(p.platforms) ? p.platforms.join(' + ') : '';

    return {
      ID_CONTEÚDO: id,
      TÍTULO_INTERNO: p.title_internal || '',
      ID_PROJETO: x.project_id,
      FORMATO: p.format || '',
      OBJETIVO: p.objective || '',
      SESSÕES_ALVO: deriveSessions(mediaIds),
      BRUTOS_USADOS: mediaIds.join('; '),
      HOOK: p.hook || '',
      ROTEIRO: p.script || '',
      LEGENDA: p.caption || '',
      CTA: p.cta || '',
      CAPA: p.hero_media_id ? `${p.hero_media_id} — HERO do plano` : '',
      STATUS_EDIÇÃO: 'IDEIA',
      STATUS_APROVAÇÃO: 'PENDENTE',
      PLATAFORMAS: platforms,
      ARQUIVO_FINAL: '',
      ID_CALENDÁRIO: '',
      OBSERVAÇÕES:
        `Gerado automaticamente pelo Projeto SM3. Requer aprovação humana antes de qualquer publicação. ` +
        `Racional: ${String(p.rationale || '').trim()}`,
      PRIORIDADE: normalizePriority(p.priority),
      DEPENDÊNCIA: p.dependency || '',
      ORDEM_EDITORIAL: index + 1,

      PLAN_STATUS: 'AI_PLANNED',
      PLAN_VERSION: PLAN_VERSION,
      PLAN_KEY: p.plan_key || '',
      PLAN_PROVIDER: x.provider || '',
      PLAN_MODEL: x.model || '',
      PLAN_RUN_ID: x.response_id,
      PLAN_CONFIDENCE: x.confidence,
      CURATION_RUN_ID: x.curation_run_id,
      TEMPLATE_ID: p.template_id || '', // legacy compatibility only
      CONTENT_TEMPLATE_ID: String(p.format || '').toUpperCase() === 'REEL' ? '' : (p.template_id || ''),
      COVER_TEMPLATE_ID: String(p.format || '').toUpperCase() === 'REEL' ? (p.template_id || '') : '',
      ART_DIRECTION_PROFILE_ID: (templateById.get(String(p.template_id || '')) || {}).PERFIL_MOTOR || '',

      EDITORIAL_APPROVAL_STATUS: 'PENDENTE',
      EDITORIAL_COMMITTED_STATUS: '',
      EDITORIAL_APPROVAL_NOTES: '',
      EDITORIAL_DECIDED_AT: '',
      EDITORIAL_APPROVAL_VERSION: 'SM3_EDITORIAL_GATE_V2',
      EDITORIAL_APPROVAL_SOURCE: '',

      FINAL_APPROVAL_STATUS: 'PENDENTE',
      FINAL_COMMITTED_STATUS: '',
      FINAL_APPROVAL_NOTES: '',
      FINAL_APPROVAL_DECIDED_AT: '',
      FINAL_APPROVAL_VERSION: '',
      FINAL_APPROVAL_SOURCE: '',

      PRODUCTION_STATUS: 'NOT_READY',
      RENDER_STATUS: 'NOT_STARTED',
      RENDER_ID: '',
      RENDER_RECIPE_ID: '',
      QA_STATUS: 'PENDING',
      QA_NOTES: '',
      PIPELINE_STATE: 'EDITORIAL_PENDING',
      STATE_UPDATED_AT: now,
      STATE_VERSION: 'SM3_STATE_V2',
      FINAL_ARTIFACT_HASH: '',

      PROJECT_STRATEGY: x.project_strategy || '',
      GENERATED_AT: now
    };
  });

  out.push({
    json: {
      project_id: x.project_id,
      content_rows: rows,
      project_write: projectWrite
    }
  });
}

return out;

const out = [];
for (const item of $input.all()) {
  for (const row of (item.json.content_rows || [])) out.push({json: row});
}
return out;

return [{
  json:{
    workflow:'PROJETO_SM3_04_CONTENT_PLAN',
    status:'CONTENT_PLAN_WRITTEN',
    message:'Plano de conteúdo persistido. Todos os itens permanecem com STATUS_APROVAÇÃO=PENDENTE.',
    completed_at:new Date().toISOString()
  }
}];

return [{json:{
  workflow:'PROJETO_SM3_04_CONTENT_PLAN',
  status:'PROJECT_STATE_REPAIRED',
  message:'04_CONTEUDOS já continha o plano atual; apenas o estado de 01_PROJETOS foi reconciliado.',
  completed_at:new Date().toISOString()
}}];

const items = $input.all().map(i => i.json);
const statuses = items.map(x => x.status || x.route_key || '').filter(Boolean);

let finalStatus = 'CONTENT_PLAN_COMPLETE';
if (statuses.includes('NO_CHANGES')) finalStatus = 'NO_CHANGES';
if (statuses.includes('PROJECT_STATE_REPAIRED')) finalStatus = 'PROJECT_STATE_REPAIRED';
if (statuses.includes('CONTENT_PLAN_WRITTEN')) finalStatus = 'CONTENT_PLAN_WRITTEN';

return [{
  json: {
    workflow: 'PROJETO_SM3_04_CONTENT_PLAN',
    status: finalStatus,
    completed_at: new Date().toISOString()
  }
}];
